-- Plates move into a dated history (db/04b). Since Sept 2025 a Punjab plate belongs to its owner and
-- can move to another car, and cars re-registered from another province get a new plate, so a plate
-- doesn't identify a car for life. Edited by hand: the data copy, the triggers and the
-- "needs an identifier" constraint trigger at the end aren't generated by drizzle-kit.
CREATE TYPE "public"."registration_end_reason" AS ENUM('plate_moved', 're_registered', 'correction');--> statement-breakpoint
CREATE TABLE "car_registrations" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"car_id" uuid NOT NULL,
	"reg_no" varchar(15) NOT NULL,
	"reg_year" smallint,
	"valid_from" timestamp with time zone DEFAULT now() NOT NULL,
	"valid_to" timestamp with time zone,
	"ended_reason" "registration_end_reason",
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "car_registrations_reg_no_normalised" CHECK ("car_registrations"."reg_no" ~ '^[A-Z0-9]{3,15}$' AND "car_registrations"."reg_no" ~ '[A-Z]' AND "car_registrations"."reg_no" ~ '[0-9]'),
	CONSTRAINT "car_registrations_reg_year_range" CHECK ("car_registrations"."reg_year" BETWEEN 1950 AND 2100),
	CONSTRAINT "car_registrations_dates" CHECK ("car_registrations"."valid_to" IS NULL OR "car_registrations"."valid_to" >= "car_registrations"."valid_from"),
	CONSTRAINT "car_registrations_end_reason" CHECK (("car_registrations"."valid_to" IS NULL) = ("car_registrations"."ended_reason" IS NULL))
);
--> statement-breakpoint
ALTER TABLE "cars" DROP CONSTRAINT "cars_reg_no_unique";--> statement-breakpoint
ALTER TABLE "cars" DROP CONSTRAINT "cars_has_identifier";--> statement-breakpoint
ALTER TABLE "cars" DROP CONSTRAINT "cars_reg_no_normalised";--> statement-breakpoint
ALTER TABLE "cars" DROP CONSTRAINT "cars_reg_year_range";--> statement-breakpoint
DROP INDEX "cars_reg_no_trgm";--> statement-breakpoint
ALTER TABLE "car_registrations" ADD CONSTRAINT "car_registrations_car_id_cars_id_fk" FOREIGN KEY ("car_id") REFERENCES "public"."cars"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "car_registrations_current_reg_no" ON "car_registrations" USING btree ("reg_no") WHERE "car_registrations"."valid_to" IS NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "car_registrations_current_per_car" ON "car_registrations" USING btree ("car_id") WHERE "car_registrations"."valid_to" IS NULL;--> statement-breakpoint
CREATE INDEX "car_registrations_reg_no_trgm" ON "car_registrations" USING gin ("reg_no" gin_trgm_ops);--> statement-breakpoint
CREATE INDEX "car_registrations_car_id_index" ON "car_registrations" USING btree ("car_id");--> statement-breakpoint
