INSERT INTO "car_registrations" ("car_id", "reg_no", "reg_year", "valid_from")
SELECT "id", "reg_no", "reg_year", "created_at" FROM "cars" WHERE "reg_no" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "cars" DROP COLUMN "reg_no";--> statement-breakpoint
ALTER TABLE "cars" DROP COLUMN "reg_year";
