-- A car needs a chassis number or at least one registration. Checked at commit (DEFERRABLE INITIALLY
-- DEFERRED), so a car and its first plate can be inserted in either order inside one transaction.
CREATE OR REPLACE FUNCTION check_car_has_identifier() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  target uuid;
  chassis varchar;
BEGIN
  IF TG_TABLE_NAME = 'cars' THEN
    target := NEW.id;
  ELSE
    target := OLD.car_id;
  END IF;
  SELECT chassis_no INTO chassis FROM cars WHERE id = target;
  IF NOT FOUND THEN
    RETURN NULL; -- the car itself was deleted in the same transaction
  END IF;
  IF chassis IS NULL AND NOT EXISTS (SELECT 1 FROM car_registrations WHERE car_id = target) THEN
    RAISE EXCEPTION 'car % needs a chassis number or a registration', target
      USING ERRCODE = 'check_violation', CONSTRAINT = 'cars_has_identifier';
  END IF;
  RETURN NULL;
END;
$$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER cars_has_identifier
  AFTER INSERT OR UPDATE OF chassis_no ON cars
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_car_has_identifier();
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER car_registrations_keep_identifier
  AFTER DELETE OR UPDATE OF car_id ON car_registrations
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_car_has_identifier();
